CREATE TABLE t(a INTEGER, b TEXT);
WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<100000) INSERT INTO t SELECT x, hex(x*7919) FROM c;
CREATE INDEX ib ON t(b);
SELECT count(*), sum(a) FROM t WHERE b LIKE '%A%';
SELECT substr(b,1,2) k, count(*) FROM t GROUP BY k ORDER BY 2 DESC LIMIT 3;
